def _direct_hits(
    self, components: dict[int, dict[str, str]]
) -> dict[tuple[str | None, str, str], dict[int, dict]]:
    """Find the components directly hit by every vulnerability kind.

    Returns a mapping from an impact-group key
    ``(source, vulnerability id, matched package)`` — ``source`` is None
    for a manually registered vulnerability and the source name for an
    imported OSV record — to a mapping of directly hit component ids to
    the hit description recorded at that terminal: ``severity``,
    ``severity_basis`` and ``matched_conditions``.

    Manual observations hit components by their verbatim package name and
    carry no version conditions or severity basis. OSV records match on
    the normalized PyPI package name and on the union of explicit
    versions and ECOSYSTEM ranges compared with PEP 440; a candidate
    component whose version cannot be parsed is a query error that
    points out the component. Gathering both kinds here lets dependency
    propagation, path selection and record generation share one code
    path.
    """
    groups: dict[tuple[str | None, str, str], dict[int, dict]] = {}

    for observation in self.connection.execute(
        "SELECT id, component_name, severity FROM vulnerabilities"
    ):
        matched_name = str(observation["component_name"])
        key = (None, str(observation["id"]), matched_name)
        detail = {
            "severity": str(observation["severity"]),
            "severity_basis": None,
            "matched_conditions": None,
        }
        terminals = groups.setdefault(key, {})
        for component_id, component in components.items():
            if component["name"] == matched_name:
                terminals[component_id] = detail

    records = self._osv_records()
    if records:
        by_package: dict[str, list[dict]] = {}
        for record in records:
            by_package.setdefault(record["package_name"], []).append(record)

        for component_id, component in components.items():
            if component["ecosystem"] != "pypi":
                continue
            normalized = normalize_pypi_name(component["name"])
            candidates = by_package.get(normalized)
            if candidates is None:
                continue
            try:
                version = Version(component["version"])
            except InvalidVersion as error:
                raise ValueError(
                    f"组件 {component['service']}/{component['ecosystem']}/"
                    f"{component['name']}/{component['version']} 版本无法解析"
                ) from error
            for record in candidates:
                matched_conditions = [
                    _format_condition(condition)
                    for condition in record["conditions"]
                    if _condition_matches(condition, version)
                ]
                if matched_conditions:
                    key = (record["source"], record["id"], normalized)
                    groups.setdefault(key, {})[component_id] = {
                        "severity": record["severity"],
                        "severity_basis": (
                            "default"
                            if record["severity_default"]
                            else "declared"
                        ),
                        "matched_conditions": matched_conditions,
                    }
    return groups

def _components_by_id(
    self, service: str | None = None
) -> dict[int, dict[str, str]]:
    if service is None:
        rows = self.connection.execute(
            "SELECT id, service, ecosystem, name, version FROM components"
        )
    else:
        rows = self.connection.execute(
            "SELECT id, service, ecosystem, name, version FROM components "
            "WHERE service = ?",
            (service,),
        )
    return {
        int(row["id"]): {
            "service": str(row["service"]),
            "ecosystem": str(row["ecosystem"]),
            "name": str(row["name"]),
            "version": str(row["version"]),
        }
        for row in rows
    }

def _dependency_edges(
    self, service: str | None = None
) -> tuple[dict[int, list[int]], dict[int, list[int]]]:
    forward: dict[int, list[int]] = {}
    reverse: dict[int, list[int]] = {}
    if service is None:
        rows = self.connection.execute(
            "SELECT dependent_id, dependency_id FROM dependencies"
        )
    else:
        # Dependencies only ever connect components of the same service,
        # so restricting both endpoints keeps a service-scoped graph closed.
        rows = self.connection.execute(
            """
            SELECT d.dependent_id, d.dependency_id
            FROM dependencies d
            JOIN components c1 ON c1.id = d.dependent_id
            JOIN components c2 ON c2.id = d.dependency_id
            WHERE c1.service = ? AND c2.service = ?
            """,
            (service, service),
        )
    for row in rows:
        dependent = int(row["dependent_id"])
        dependency = int(row["dependency_id"])
        forward.setdefault(dependent, []).append(dependency)
        reverse.setdefault(dependency, []).append(dependent)
    return forward, reverse

@staticmethod
def _component_identity_key(
    component: dict[str, str]
) -> tuple[str, str, str]:
    """Identity fields used as the deterministic path tie-breaker."""
    return (
        component["ecosystem"],
        component["name"],
        component["version"],
    )

@staticmethod
def _reconstruct_path(
    component_id: int,
    distance: dict[int, int],
    forward: dict[int, list[int]],
    components: dict[int, dict[str, str]],
) -> list[int]:
    """Reconstruct the shortest path, ties broken by component identity."""
    path_ids = [component_id]
    while distance[path_ids[-1]] > 0:
        current = path_ids[-1]
        candidates = [
            nxt
            for nxt in forward.get(current, ())
            if distance.get(nxt) == distance[current] - 1
        ]
        path_ids.append(
            min(
                candidates,
                key=lambda nxt: Catalog._component_identity_key(
                    components[nxt]
                ),
            )
        )
    return path_ids

@staticmethod
def _propagate_distances(
    terminals: dict[int, dict],
    reverse: dict[int, list[int]],
    bounds: frozenset[int] | set[int] | None = None,
) -> dict[int, int]:
    """Fewest dependency hops from each component to a directly hit one.

    Multi-source BFS over the reverse dependency edges starting from all
    directly hit components of one vulnerability/source/package group.
    When ``bounds`` is given, only components inside it receive a
    distance — this is the single propagation rule used by both the
    directory/service-wide query (no bounds: every component the group
    reaches) and the full-identity query (bounds = the target's forward
    dependency closure). Restricting the BFS leaves every distance
    inside the closure identical to the unbounded run. Cycles are
    handled by the distance map, so every component is visited at most
    once and a path never repeats a component.
    """
    distance: dict[int, int] = {}
    for component_id in sorted(terminals):
        if bounds is None or component_id in bounds:
            distance[component_id] = 0
    queue = deque(distance)
    while queue:
        node = queue.popleft()
        for dependent in reverse.get(node, ()):
            if bounds is not None and dependent not in bounds:
                continue
            if dependent not in distance:
                distance[dependent] = distance[node] + 1
                queue.append(dependent)
    return distance

def _impact_record(
    self,
    components: dict[int, dict[str, str]],
    group_key: tuple[str | None, str, str],
    terminals: dict[int, dict],
    component_id: int,
    distance: dict[int, int],
    forward: dict[int, list[int]],
) -> dict:
    """Build the one impact record of a component within one hit group.

    This is the single record-construction rule shared by the
    directory-wide, service-scoped and full-identity queries, so the
    direct/indirect flag, the dependency path, the source, the severity
    and its basis and the matched version conditions can never be
    explained differently depending on how the record was queried.

    The path is reconstructed by the one shortest-path rule — fewest

"""Business regression tests for OSV matching of PyPI versions with epochs.

These tests exercise the public catalog behavior — components are
registered, a local OSV source is imported, and the impacts a user would
query are inspected — rather than only checking that version strings parse.
They guard the PEP 440 epoch rules: the epoch before ``!`` dominates
ordering (never string comparison), ``1!2.0`` equals ``1!2.0.0`` in
conditions while staying a distinct component identity, and interval
endpoints keep their introduced/fixed/last_affected inclusion semantics
when epochs and prereleases are involved.
"""

import unittest

from supply_guard.catalog import Catalog


def osv_record(identifier, package="flask", **affected):
    entry = {"package": {"ecosystem": "PyPI", "name": package}}
    entry.update(affected)
    return {"id": identifier, "affected": [entry]}


def epoch_range(*events):
    return [{"type": "ECOSYSTEM", "events": [dict([event]) for event in events]}]


class EpochOrderingTests(unittest.TestCase):
    def setUp(self) -> None:
        self.catalog = Catalog()

    def tearDown(self) -> None:
        self.catalog.close()

    def impacted_versions(self):
        return {r["component"]["version"] for r in self.catalog.impact()}

    def test_epoch_orders_numerically_not_lexically(self) -> None:
        # 1!9.0 < 1!10.0 per PEP 440; a textual comparison would order them
        # the other way and empty the interval.
        for version in ("1!2.0", "1!9.0", "1!10.0"):
            self.catalog.add_component("api", "pypi", "flask", version)
        self.catalog.import_osv(
            "src",
            [
                osv_record(
                    "CVE-1",
                    ranges=epoch_range(("introduced", "1!9.0"), ("fixed", "1!10.0")),
                )
            ],
        )
        self.assertEqual(self.impacted_versions(), {"1!9.0"})

    def test_higher_epoch_beats_any_lower_epoch_release(self) -> None:
        # 2!1.0 > 1!99.0: dropping the epoch would compare 1.0 with 99.0 and
        # pull the old-epoch component into an interval it is far below.
        self.catalog.add_component("api", "pypi", "flask", "1!99.0")
        self.catalog.add_component("api", "pypi", "flask", "2!1.0")
        self.catalog.import_osv(
            "src",
            [osv_record("CVE-1", ranges=epoch_range(("introduced", "2!1.0")))],
        )
        self.assertEqual(self.impacted_versions(), {"2!1.0"})

    def test_lower_epoch_stays_below_upper_bound_of_higher_epoch(self) -> None:
        self.catalog.add_component("api", "pypi", "flask", "1!99.0")
        self.catalog.add_component("api", "pypi", "flask", "2!1.0")
        self.catalog.import_osv(
            "src",
            [
                osv_record(
                    "CVE-1",
                    ranges=epoch_range(("introduced", "0"), ("fixed", "2!1.0")),
                )
            ],
        )
        self.assertEqual(self.impacted_versions(), {"1!99.0"})

    def test_epoch_equivalent_release_segments_match_explicit_version(self) -> None:
        # 1!2.0 and 1!2.0.0 are equal as PEP 440 versions, so one explicit
        # condition hits both; the catalog still keeps two distinct component
        # identities with their verbatim version spellings.
        self.catalog.add_component("api", "pypi", "flask", "1!2.0")
        self.catalog.add_component("api", "pypi", "flask", "1!2.0.0")
        self.catalog.import_osv("src", [osv_record("CVE-1", versions=["1!2.0.0"])])
        records = self.catalog.impact()
        self.assertEqual(len(records), 2)
        versions = {r["component"]["version"] for r in records}
        self.assertEqual(versions, {"1!2.0", "1!2.0.0"})
        for record in records:
            self.assertEqual(record["matched_conditions"], ["==1!2.0.0"])
            self.assertTrue(record["direct"])
        # Two independent identities remain in the directory.
        self.assertEqual(self.catalog.summary().components, 2)

    def test_epoch_equivalent_release_segments_match_interval_bounds(self) -> None:
        # An interval introduced at 1!2.0.0 also starts at the component
        # registered as 1!2.0, and a fixed 1!3.0.0 excludes 1!3.0.
        self.catalog.add_component("api", "pypi", "flask", "1!2.0")
        self.catalog.add_component("api", "pypi", "flask", "1!3.0")
        self.catalog.import_osv(
            "src",
            [
                osv_record(
                    "CVE-1",
                    ranges=epoch_range(
                        ("introduced", "1!2.0.0"), ("fixed", "1!3.0.0")
                    ),
                )
            ],
        )
        self.assertEqual(self.impacted_versions(), {"1!2.0"})


